import { generateCodexOAuthCredentialRevision } from "../src/profile-cipher.service.js";
import { CodexProfileStore } from "../src/profile-store.service.js";
import {
  CodexSubscriptionProfile,
  OpenAICompatibleChatCompletionRequest,
} from "../src/schemas.js";
import {
  CodexSubscriptionLoginConfigLive,
  CodexSubscriptionLoginConfigService,
} from "../src/subscription-login.config.js";
import {
  UpstashCodexOAuthProfileCommitLive,
  UpstashKeyValueStoreLive,
} from "../src/upstash-key-value-store.layer.js";

declare const process: {
  exitCode: number | undefined;
};

const previewUrlConfig = Config.url("BUNDJIL_CODEX_PROXY_PREVIEW_URL");
const internalTokenConfig = Config.redacted(
  "BUNDJIL_CODEX_PROXY_INTERNAL_TOKEN"
);

const configProviderLayer = ConfigProvider.layer(ConfigProvider.fromEnv());
const cipherConfigLayer = CodexOAuthProfileCipherConfigLive.pipe(
  Layer.provide(configProviderLayer)
);
const cipherLayer = CodexOAuthProfileCipherLive.pipe(
  Layer.provide(cipherConfigLayer)
);
const profileStoreLayer = CodexProfileStoreEncryptedKeyValueLive.pipe(
  Layer.provideMerge(Layer.merge(cipherLayer, UpstashKeyValueStoreLive))
);
const profileCommitLayer = UpstashCodexOAuthProfileCommitLive.pipe(
  Layer.provide(cipherLayer)
);
const loginConfigLayer = CodexSubscriptionLoginConfigLive.pipe(
  Layer.provide(configProviderLayer)
);

const requestBody = Schema.encodeSync(
  Schema.fromJsonString(OpenAICompatibleChatCompletionRequest)
)(
  Schema.decodeUnknownSync(OpenAICompatibleChatCompletionRequest)({
    messages: [{ content: "Reply only: OK.", role: "user" }],
    model: "gpt-5.5",
    stream: true,
  })
);

const HostedStagedRefreshProof = Schema.Struct({
  concurrentAuthenticatedSuccess: Schema.Boolean,
  finalExpiryValid: Schema.Boolean,
  finalProfileSubscription: Schema.Boolean,
  finalRevisionChanged: Schema.Boolean,
  responsesAreSse: Schema.Boolean,
  responsesComplete: Schema.Boolean,
  stagedExpiry: Schema.Boolean,
});

const HostedStagedRefreshProofSuccess = Schema.Struct({
  result: HostedStagedRefreshProof,
  status: Schema.Literal("proved"),
});

const HostedStagedRefreshProofBlocked = Schema.Struct({
  status: Schema.Literal("blocked"),
});

const encodeProofSuccess = Schema.encodeSync(
  Schema.fromJsonString(HostedStagedRefreshProofSuccess)
);
const encodeProofBlocked = Schema.encodeSync(
  Schema.fromJsonString(HostedStagedRefreshProofBlocked)
);

class HostedProofRequestError extends Data.TaggedError(
  "HostedProofRequestError"
)<{ readonly cause: unknown }> {}

const fetchResponse = (request: Request) =>
  Effect.tryPromise({
    catch: (cause) => new HostedProofRequestError({ cause }),
    try: () => fetch(request),
  });

const readResponse = (response: Response) =>
  Effect.tryPromise({
    catch: (cause) => new HostedProofRequestError({ cause }),
    try: () => response.text(),
  });

const program = Effect.gen(function* proveHostedStagedRefresh() {
  const input = yield* CodexSubscriptionLoginConfigService;
  const previewUrl = yield* previewUrlConfig;
  const internalToken = yield* internalTokenConfig;
  const store = yield* CodexProfileStore;
  const commit = yield* CodexOAuthProfileCommit;
  const profile = yield* store.getProfile(input.subject);

  if (profile.profileKind !== "subscription") {
    return yield* new CodexSubscriptionAuthError({
      message: "Only an isolated subscription profile can be staged.",
      operation: "completeLogin",
      reason: "tokenMetadataInvalid",
    });
  }

  const now = yield* Clock.currentTimeMillis;
  const stagedRevision = yield* generateCodexOAuthCredentialRevision();
  const stagedProfile = yield* Schema.decodeUnknownEffect(
    CodexSubscriptionProfile
  )({
    ...profile,
    accessToken: Redacted.value(profile.accessToken),
    accountId: Redacted.value(profile.accountId),
    credentialRevision: stagedRevision,
    expiresAtEpochMillis: now - 1,
    refreshToken: Redacted.value(profile.refreshToken),
    updatedAtEpochMillis: now,
  });

  yield* commit.replace({
    expectedRevision: profile.credentialRevision,
    profile: stagedProfile,
  });

  const completionUrl = new URL("/v1/chat/completions", previewUrl);
  const request = () =>
    new Request(completionUrl, {
      body: requestBody,
      headers: {
        authorization: `Bearer ${Redacted.value(internalToken)}`,
        "content-type": "application/json",
      },
      method: "POST",
    });
  const responses = yield* Effect.all(
    [fetchResponse(request()), fetchResponse(request())],
    { concurrency: "unbounded" }
  );
  const bodies = yield* Effect.all(responses.map(readResponse), {
    concurrency: "unbounded",
  });
  const finalProfile = yield* store.getProfile(input.subject);
  const after = yield* Clock.currentTimeMillis;

  return HostedStagedRefreshProof.make({
    concurrentAuthenticatedSuccess: responses.every(
      (response) => response.status === 200
    ),
    finalExpiryValid: finalProfile.expiresAtEpochMillis > after,
    finalProfileSubscription: finalProfile.profileKind === "subscription",
    finalRevisionChanged:
      finalProfile.profileKind === "subscription" &&
      finalProfile.credentialRevision !== stagedRevision,
    responsesAreSse: responses.every(
      (response) => response.headers.get("content-type") === "text/event-stream"
    ),
    responsesComplete: bodies.every((body) => body.includes("data: [DONE]")),
    stagedExpiry: stagedProfile.expiresAtEpochMillis <= now,
  });
}).pipe(
  Effect.provide(
    Layer.mergeAll(
      profileStoreLayer,
      profileCommitLayer,
      loginConfigLayer,
      ConfigProvider.layer(ConfigProvider.fromEnv())
    )
  )
);

const exit = await Effect.runPromiseExit(program);

if (Exit.isSuccess(exit)) {
  console.log(
    encodeProofSuccess({
      result: exit.value,
      status: "proved",
    })
  );
} else {
  console.error(encodeProofBlocked({ status: "blocked" }));
  process.exitCode = 1;
}

### stage-script
import {
  Cause,
  Clock,
  ConfigProvider,
  Effect,
  Exit,
  Layer,
  Option,
  Redacted,
  Schema,
} from "effect";

import { CodexOAuthProfileCommit } from "../src/commit.service.js";
import { CodexSubscriptionAuthError } from "../src/errors.js";
import {
  CodexOAuthProfileCipherConfigLive,
  CodexOAuthProfileCipherLive,
  CodexProfileStoreEncryptedKeyValueLive,
} from "../src/live.layer.js";
import { generateCodexOAuthCredentialRevision } from "../src/profile-cipher.service.js";
import { CodexProfileStore } from "../src/profile-store.service.js";
import { CodexSubscriptionProfile } from "../src/schemas.js";
import {
  CodexSubscriptionLoginConfigLive,
  CodexSubscriptionLoginConfigService,
} from "../src/subscription-login.config.js";
import {
  UpstashCodexOAuthProfileCommitLive,
  UpstashKeyValueStoreLive,
} from "../src/upstash-key-value-store.layer.js";

declare const process: {
  exitCode: number | undefined;
};

const configProviderLayer = ConfigProvider.layer(ConfigProvider.fromEnv());
const cipherConfigLayer = CodexOAuthProfileCipherConfigLive.pipe(
  Layer.provide(configProviderLayer)
);
const cipherLayer = CodexOAuthProfileCipherLive.pipe(
  Layer.provide(cipherConfigLayer)
);
const profileStoreLayer = CodexProfileStoreEncryptedKeyValueLive.pipe(
  Layer.provideMerge(Layer.merge(cipherLayer, UpstashKeyValueStoreLive))
);
const profileCommitLayer = UpstashCodexOAuthProfileCommitLive.pipe(
  Layer.provide(cipherLayer)
);
const loginConfigLayer = CodexSubscriptionLoginConfigLive.pipe(
  Layer.provide(configProviderLayer)
);

const NearExpiryProfileStageResult = Schema.Struct({
  expiryForced: Schema.Boolean,
  profileKindSubscription: Schema.Boolean,
  stagedWithNewRevision: Schema.Boolean,
});

const NearExpiryProfileStageSuccess = Schema.Struct({
  result: NearExpiryProfileStageResult,
  status: Schema.Literal("staged"),
});

const NearExpiryProfileStageBlocked = Schema.Struct({
  errorTag: Schema.NonEmptyString,
  status: Schema.Literal("blocked"),
});

const encodeStageSuccess = Schema.encodeSync(
  Schema.fromJsonString(NearExpiryProfileStageSuccess)
);
const encodeStageBlocked = Schema.encodeSync(
  Schema.fromJsonString(NearExpiryProfileStageBlocked)
);

const program = Effect.gen(function* stageNearExpiryProfile() {
  const input = yield* CodexSubscriptionLoginConfigService;
  const store = yield* CodexProfileStore;
  const commit = yield* CodexOAuthProfileCommit;
  const profile = yield* store.getProfile(input.subject);

  if (profile.profileKind !== "subscription") {
    return yield* new CodexSubscriptionAuthError({
      message: "Only an isolated subscription profile can be staged.",
      operation: "completeLogin",
      reason: "tokenMetadataInvalid",
    });
  }

  const now = yield* Clock.currentTimeMillis;
  const credentialRevision = yield* generateCodexOAuthCredentialRevision();
  const stagedProfile = yield* Schema.decodeUnknownEffect(
    CodexSubscriptionProfile
  )({
    ...profile,
    accessToken: Redacted.value(profile.accessToken),
    accountId: Redacted.value(profile.accountId),
    credentialRevision,
    expiresAtEpochMillis: now - 1,
    refreshToken: Redacted.value(profile.refreshToken),
    updatedAtEpochMillis: now,
  });

  yield* commit.replace({
    expectedRevision: profile.credentialRevision,
    profile: stagedProfile,
  });

  return NearExpiryProfileStageResult.make({
    expiryForced: true,
    profileKindSubscription: true,
    stagedWithNewRevision: true,
  });
}).pipe(
  Effect.provide(
    Layer.mergeAll(profileStoreLayer, profileCommitLayer, loginConfigLayer)
  )
);

const exit = await Effect.runPromiseExit(program);

if (Exit.isSuccess(exit)) {
  console.log(
    encodeStageSuccess({
      result: exit.value,
      status: "staged",
    })
  );
} else {
  const failure = Cause.findErrorOption(exit.cause);
  const errorTag = Option.match(failure, {
    onNone: () => "UnknownCause",
    onSome: (error) =>
      typeof error === "object" &&
      error !== null &&
      "_tag" in error &&
      typeof error._tag === "string"
        ? error._tag
        : "UnknownFailure",
  });

  console.error(
    encodeStageBlocked({
      errorTag,
      status: "blocked",
    })
  );
  process.exitCode = 1;
}

### proof-readme
  `KeyValueStore.layerMemory`.
- Leave Vercel/Upstash credentials in ignored env files or rotate them through
  provider dashboards; do not print values in rollback notes.

## Safe Secret Handling

Do not log, snapshot, or include access tokens, refresh tokens, authorization
codes, raw OAuth responses, or private prompts in errors. Public tagged errors
only include safe fields such as operation names, profile ids, hashed subject
keys, timestamps, and sanitized messages.

## Trusted-Local Subscription Login

Run the broker only on the trusted owner machine. It requires the personal
Upstash and profile-encryption configuration documented above, plus the
non-secret subject identifier:

```bash
REDACTED \
  bun run --filter @bundjil/codex-oauth login:subscription
```

Optional non-secret settings are:

- `BUNDJIL_CODEX_PROFILE_CONNECTOR_ID`, default `bundjil-local`
- `BUNDJIL_CODEX_PROFILE_INSTALLATION_ID`, default `agent-dev`
- `BUNDJIL_CODEX_PROFILE_ID`, default `default`
- `BUNDJIL_CODEX_LOGIN_CALLBACK_TIMEOUT`, default `5 minutes`

The command prints only a Schema-encoded result containing the profile id,
ChatGPT mode, valid-expiry category, refresh capability, and encrypted-store
confirmation. It never prints the authorization URL, callback query, code,
state, verifier, tokens, ID token, account id, provider response, prompt, or
model output.

Package typechecking includes `src`, `test`, and `scripts`, so the executable
composition is checked alongside its service contracts. The build remains
source-only and does not emit CLI entrypoints into the package library output.

The callback is local-only. There is deliberately no `/oauth/start`,
`/oauth/callback`, Vercel callback, Eve callback, or browser-bundle import.
Hosted code reads the resulting encrypted profile in later tasks; it never
conducts the interactive login.

After a successful trusted-local login, verify the persisted profile from the
same private shell:

```bash
bun run --filter @bundjil/codex-oauth proof:stored-profile
```

The proof reads the persisted envelope through Effect `KeyValueStore`, decodes
the canonical encrypted-envelope Schema, and decrypts only inside the trusted
process through the profile store and cipher services. Its Schema-encoded
output contains only `found`, `envelopeVersion2`, `ciphertextPresent`,
`profileKindSubscription`, `refreshCapable`, `expiryValid`,
`requiresReauthenticationFalse`, and `markerLeakFalse` booleans. It never
prints the storage key, subject hash, revision, timestamps, ciphertext,
configuration, credentials, account metadata, claims, or raw payload.

## Trusted-Local Profile Import

The temporary local-import workaround is documented in
[`docs/product-specs/codex-local-profile-import-workaround.md`](../../docs/product-specs/codex-local-profile-import-workaround.md).
It is not a supported hosted OAuth flow: it does not reuse the Codex CLI
client, redirect URI, browser session, PKCE exchange, or refresh token.

Run it only on the trusted machine with an active local Codex ChatGPT login:

```bash
bun run --filter @bundjil/codex-oauth import:local-profile
```

That command remains a rollback-only access-import path. The refresh-capable
personal preview path uses `login:subscription`. For the separate local
filesystem proof, use `import:local-profile:filesystem`; it never composes
Upstash.

The command reads configuration through Effect `Config` and
`ConfigProvider.fromEnv()`. It needs the existing encryption and Upstash
configuration plus these explicit, non-secret profile fields:

- `BUNDJIL_CODEX_PROFILE_PRINCIPAL_ID`
- `BUNDJIL_CODEX_PROFILE_CONNECTOR_ID`
- `BUNDJIL_CODEX_PROFILE_INSTALLATION_ID`
- `BUNDJIL_CODEX_PROFILE_ID`

`BUNDJIL_CODEX_LOCAL_AUTH_FILE` is optional and defaults to
`$HOME/.codex/auth.json` for this command only. The importer uses
`BUNDJIL_CODEX_LOCAL_ACCESS_TOKEN_TTL` to calculate the short-lived profile
expiry; it defaults to one hour from Codex's local `last_refresh` timestamp.
When overriding it, use Effect duration syntax such as `"1 hour"` or
`"720 hours"`, not abbreviated values such as `1h`.
Set `BUNDJIL_CODEX_ACCOUNT_ID` only in proxy configuration when the direct
provider needs its optional account header; the importer never reads it from
the Codex cache.

Success output is schema-backed metadata only: the profile id, `chatgpt` mode,
the re-import-required state, valid-expiry status, and encrypted-store
confirmation. Filesystem-import failure output additionally includes a fixed
safe operation category such as `decodeCache`, `validateExpiry`,
`profileCipher`, or `storage`; it names no cache path, account id, cache
contents, token, prompt, or model response.

The profile contains only the current access token. When it expires, the
proxy must fail closed; renew the local Codex login if needed and run the
import command again. Do not add automatic refresh around this workaround.

### Operator Modes

- `mock` is app-owned and the default. It needs no imported profile and never
  calls Codex.
- `local` is a trusted Bun-only proof. The filesystem importer and proxy use
  `BUNDJIL_CODEX_LOCAL_PROFILE_STORE_DIR`; Vercel rejects this mode.
- `live` is the personal Vercel preview path. The Upstash importer and proxy
  require preview-only cipher, internal-token, subject, and KV configuration.
  The package never chooses the mode or deploys Vercel.

Local and preview import commands return schema-backed, sanitized status only:

```text
status: imported
mode: chatgpt
requiresReauthentication: true
expiryStatus: valid
encryptedStore: stored
```

That output does not establish durable authentication. It records an
access-token-only profile which must be re-imported after expiry or upstream
authorization failure. The package deliberately does not implement hosted

