import { ConfigProvider, Effect, Layer, Schema } from "effect";
import * as KeyValueStore from "effect/unstable/persistence/KeyValueStore";

import { EncryptedCodexOAuthProfile } from "../src/schemas.js";
import {
  CodexSubscriptionLoginConfigLive,
  CodexSubscriptionLoginConfigService,
} from "../src/subscription-login.config.js";
import { codexOAuthProfileStorageKey } from "../src/storage-keys.js";
import { UpstashKeyValueStoreLive } from "../src/upstash-key-value-store.layer.js";

const envelopeJson = Schema.fromJsonString(
  Schema.toCodecJson(EncryptedCodexOAuthProfile)
);
const configLayer = CodexSubscriptionLoginConfigLive.pipe(
  Layer.provide(ConfigProvider.layer(ConfigProvider.fromEnv()))
);

const program = Effect.gen(function* readPreviewCipherKeyId() {
  const input = yield* CodexSubscriptionLoginConfigService;
  const store = yield* KeyValueStore.KeyValueStore;
  const key = yield* codexOAuthProfileStorageKey(input.subject);
  const encoded = yield* store.get(key);

  if (encoded === undefined) {
    return yield* Effect.fail(new Error("Preview profile envelope absent."));
  }

  const envelope = yield* Schema.decodeUnknownEffect(envelopeJson)(encoded);
  return envelope.keyId;
}).pipe(Effect.provide(Layer.merge(configLayer, UpstashKeyValueStoreLive)));

console.log(await Effect.runPromise(program));

