const required = (name: string): string => {
  const value = Bun.env[name];
  if (value === undefined || value.length === 0) {
    throw new Error(`Missing required identity input: ${name}`);
  }
  return value;
};

const sha256 = async (value: string): Promise<string> => {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(value)
  );

  return Array.from(new Uint8Array(digest), (byte) =>
    byte.toString(16).padStart(2, "0")
  ).join("");
};

const namespace = required("BUNDJIL_UPSTASH_REDIS_KEY_PREFIX");
const subjectHash = await sha256(
  [
    "codex",
    "chatgpt-user",
    required("BUNDJIL_CODEX_SUBJECT_ID"),
    "https://auth.openai.com",
    required("BUNDJIL_CODEX_CONNECTOR_ID"),
    required("BUNDJIL_CODEX_INSTALLATION_ID"),
    required("BUNDJIL_CODEX_PROFILE_ID"),
  ].join("\u001F")
);

const deriveFingerprint = (storagePrefix: string) =>
  sha256(`${namespace}${storagePrefix}/${subjectHash}`);

console.log(
  JSON.stringify({
    cipherKeyId: required("BUNDJIL_CODEX_PROFILE_ENCRYPTION_KEY_ID"),
    derivedFenceKeyFingerprint: await deriveFingerprint(
      "bundjil/oauth/v1/provider/codex/profile-revision"
    ),
    derivedLockKeyFingerprint: await deriveFingerprint(
      "bundjil/oauth/v1/provider/codex/refresh-lock"
    ),
    derivedProfileKeyFingerprint: await deriveFingerprint(
