  const value = Bun.env[name];
  if (value === undefined || value.length === 0) {
    throw new Error(`Missing local Production value: ${name}`);
  }

  const child = Bun.spawn(
    [
      "bunx",
      "vercel",
      "env",
      "add",
      name,
      "production",
      "--sensitive",
      "--force",
      "--yes",
      "--scope",
      "cooper-corbetts-projects",
      "--cwd",
      repo,
    ],
    { stdin: new Blob([value]), stdout: "pipe", stderr: "pipe" }
